"""Secret-free model profiles persisted for reuse by the local application."""

from __future__ import annotations

import json
import os
import re
from datetime import UTC, datetime
from pathlib import Path

from pydantic import BaseModel, Field

from prompt_playoff.domain import ModelProfile
from prompt_playoff.persistence import advisory_lock, atomic_write_json, quarantine_corrupt_file

DEFAULT_PROFILES_PATH = Path("benchmark-results/model-profiles.json")


class SavedModelProfile(BaseModel):
    id: str = Field(pattern=r"^[a-z0-9][a-z0-9._-]{0,63}$")
    name: str = Field(min_length=1, max_length=100)
    profile: ModelProfile
    created_at: str
    updated_at: str


class ModelProfileStore:
    def __init__(self, path: Path | None = None) -> None:
        self.path = path or _default_path()
        self.lock_path = self.path.with_name(f"{self.path.name}.lock")
        self.corrupt_path: Path | None = None

    def list(self) -> list[SavedModelProfile]:
        with advisory_lock(self.lock_path):
            return sorted(self._load_unlocked(), key=lambda item: item.name.lower())

    def save(
        self, name: str, profile: ModelProfile, profile_id: str | None = None
    ) -> SavedModelProfile:
        now = _now()
        clean = profile.model_copy(update={"api_key": None})
        identifier = _slug(profile_id or name)
        with advisory_lock(self.lock_path):
            records = self._load_unlocked()
            previous = next((item for item in records if item.id == identifier), None)
            saved = SavedModelProfile(
                id=identifier,
                name=name.strip(),
                profile=clean,
                created_at=previous.created_at if previous else now,
                updated_at=now,
            )
            records = [item for item in records if item.id != identifier]
            records.append(saved)
            self._write_unlocked(records)
            return saved

    def delete(self, profile_id: str) -> bool:
        with advisory_lock(self.lock_path):
            records = self._load_unlocked()
            kept = [item for item in records if item.id != profile_id]
            if len(kept) == len(records):
                return False
            self._write_unlocked(kept)
            return True

    def _load_unlocked(self) -> list[SavedModelProfile]:
        if not self.path.exists():
            return []
        try:
            payload = json.loads(self.path.read_text(encoding="utf-8"))
            return [SavedModelProfile.model_validate(item) for item in payload.get("profiles", [])]
        except (OSError, ValueError, TypeError):
            try:
                self.corrupt_path = quarantine_corrupt_file(self.path)
            except OSError:
                self.corrupt_path = self.path
            return []

    def _write_unlocked(self, records: list[SavedModelProfile]) -> None:
        atomic_write_json(
            self.path,
            {"version": 1, "profiles": [item.model_dump(mode="json") for item in records]},
        )


def _slug(value: str) -> str:
    slug = re.sub(r"[^a-z0-9._-]+", "-", value.lower()).strip("-._")
    if not slug:
        raise ValueError("Profile name must contain at least one letter or number")
    return slug[:64]


def _now() -> str:
    return datetime.now(UTC).isoformat(timespec="seconds")


def _default_path() -> Path:
    return Path(os.getenv("PROMPT_PLAYOFF_PROFILES_PATH", DEFAULT_PROFILES_PATH)).expanduser()

from pathlib import Path

from prompt_playoff.evals import load_jsonl

DATASETS = Path(__file__).parents[1] / "src" / "prompt_playoff" / "data" / "datasets"


def test_uncovered_datasets_have_deterministic_headroom_shape():
    expected_graders = {
        "translation": {"glossary_consistency", "omission_check"},
        "summarization": {"contains_all", "length_limit"},
        "grounded-qa": {"grounding_overlap", "contains_all"},
        "agents": {"tool_success", "exact_match"},
    }
    for name, graders in expected_graders.items():
        rows = load_jsonl(DATASETS / f"{name}.jsonl")
        assert len(rows) >= 100
        assert len({row.id for row in rows}) == len(rows)
        assert len({row.input for row in rows}) == len(rows)
        assert all(set(row.graders) == graders for row in rows)


def test_translation_gold_and_glossary_follow_from_source():
    for row in load_jsonl(DATASETS / "translation.jsonl"):
        glossary = row.grader_options["glossary"]
        source = row.grader_options["source"]
        assert all(term in source for term in glossary)
        assert all(term in row.expected for term in glossary.values())


def test_summaries_require_only_verbatim_document_facts():
    for row in load_jsonl(DATASETS / "summarization.jsonl"):
        assert all(fact in row.input for fact in row.grader_options["contains"])


def test_grounded_qa_includes_unsettled_cases():
    rows = load_jsonl(DATASETS / "grounded-qa.jsonl")
    unsettled = [row for row in rows if "unsettled" in row.tags]
    assert len(unsettled) >= 20
    assert all(row.expected == "INSUFFICIENT_EVIDENCE" for row in unsettled)


def test_agent_gold_is_recomputable():
    rows = load_jsonl(DATASETS / "agents.jsonl")
    assert {tag for row in rows for tag in row.tags} >= {"calculator", "word-count"}
    for row in rows:
        if "word-count" in row.tags:
            text = row.input.split("text: ", 1)[1].split(" Return only", 1)[0]
            assert row.expected == str(len(text.rstrip(".").split()))

from prompt_playoff.domain import EvidenceLevel
from prompt_playoff.registry import Registry


def test_registry_loads() -> None:
    registry = Registry.load()
    assert len(registry.techniques) >= 14
    assert "structured.schema-first" in registry.techniques
    assert len(registry.models) >= 3


def test_a_cited_paper_can_be_opened() -> None:
    """The Techniques tab links every citation, so a citation needs a URL.

    The lint rule requires a source once evidence_level rises above heuristic,
    but not a link — a technique could arrive naming a paper with no way to
    reach it, and the tab would render dead text next to real links.
    """
    for technique in Registry.load().techniques.values():
        if technique.source is None:
            continue
        url = technique.source.url or ""
        assert url.startswith(("http://", "https://")), (
            f"{technique.id} cites {technique.source.paper!r} with no reachable URL"
        )


def test_an_unsourced_technique_admits_it_is_a_pattern() -> None:
    """The other half of the same claim: no paper means no published evidence."""
    for technique in Registry.load().techniques.values():
        if technique.source is None:
            assert technique.evidence_level is EvidenceLevel.heuristic, (
                f"{technique.id} claims {technique.evidence_level.value} evidence "
                "without naming a source"
            )
